const Imap = require('imap');
const { simpleParser } = require('mailparser');

function extractEmail(address) {
  const match = address.match(/<([^>]+)>/);
  return match ? match[1] : address.trim();
}

async function getUidByMessageIdFromUnseen(imap, folder, messageId) {
  return new Promise((resolve, reject) => {
    imap.openBox(folder, true, (err) => {
      if (err) return reject(err);

      // Сначала ищем все непрочитанные письма
      imap.search(['UNSEEN'], (err, results) => {
        if (err) return reject(err);

        if (!results.length) {
          // Нет непрочитанных писем — значит UID нет
          return resolve(null);
        }

        // Теперь среди результатов ищем письмо с нужным Message-ID
        const fetcher = imap.fetch(results, { bodies: 'HEADER.FIELDS (MESSAGE-ID)', struct: true });

        let foundUid = null;

        fetcher.on('message', (msg, seqno) => {
          let header = '';

          msg.on('body', (stream) => {
            stream.on('data', (chunk) => {
              header += chunk.toString('utf8');
            });
          });

          msg.on('attributes', (attrs) => {
            // Когда есть атрибуты и заголовок, проверяем Message-ID
            // Парсим заголовок, чтобы достать Message-ID
            const match = header.match(/Message-ID:\s*(.*)/i);
            if (match) {
              let foundMessageId = match[1].trim();
              // Иногда Message-ID в угловых скобках — очистим
              foundMessageId = foundMessageId.replace(/[<>]/g, '');
              if (foundMessageId === messageId.replace(/[<>]/g, '')) {
                foundUid = attrs.uid;
              }
            }
          });
        });

        fetcher.once('error', (err) => reject(err));
        fetcher.once('end', () => {
          resolve(foundUid);
        });
      });
    });
  });
}

async function main(input) {
  const parsed = await simpleParser(input.raw);

  const textPlain = (parsed.text || '').trim();
  const textHtml = (parsed.html || '').trim();
  const body = textPlain || textHtml || '';

  const imap = new Imap({
    user: input.imapUser,
    password: input.imapPass,
    host: input.imapHost,
    port: input.imapPort,
    tls: true,
  });

  return new Promise((resolve, reject) => {
    imap.once('ready', async () => {
      try {
        const uid = await getUidByMessageIdFromUnseen(imap, input.folder, parsed.messageId);

        resolve({
          textPlain,
          textHtml,
          body,
          subject: parsed.subject || '',
          sender: extractEmail(parsed.from?.text || ''),
          recipient: extractEmail(parsed.to?.text || ''),
          message_id: parsed.messageId || '',
          references: parsed.references?.join(' ') || '',
          date: parsed.date || null,
          folder: input.folder,
          uid,
        });
      } catch (e) {
        reject(e);
      } finally {
        imap.end();
      }
    });

    imap.once('error', reject);
    imap.connect();
  });
}

return main({
  raw: item.json.raw,
  imapUser: item.json.imap_user,
  imapPass: item.json.imap_pass,
  imapHost: item.json.imap_host,
